import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"哀岁","description":"","frontmatter":{"title":"哀岁","date":"2026-11-24T00:00:00.000Z","seq":64,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"伤时","link":"/blogs/楚辞/伤时.html"},"next":{"text":"守志","link":"/blogs/楚辞/守志.html"}},"headers":[],"relativePath":"blogs/楚辞/哀岁.md","filePath":"blogs/楚辞/哀岁.md"}'),o={name:"blogs/楚辞/哀岁.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="哀岁" tabindex="-1">哀岁 <a class="header-anchor" href="#哀岁" aria-label="Permalink to &quot;哀岁&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">旻天兮清凉，玄气兮高朗。</p><p class="poem-stanza">北风兮潦洌，草木兮苍唐。</p><p class="poem-stanza">蛜蚗兮噍噍，蝍蛆兮穰穰。</p><p class="poem-stanza">岁忽忽兮惟暮，余感时兮悽怆。</p><p class="poem-stanza">伤俗兮泥浊，矇蔽兮不章。</p><p class="poem-stanza">宝彼兮沙砾，捐此兮夜光。</p><p class="poem-stanza">椒瑛兮湟汙，葈耳兮充房。</p><p class="poem-stanza">摄衣兮缓带，操我兮墨阳。</p><p class="poem-stanza">昇车兮命仆，将驰兮四荒。</p><p class="poem-stanza">下堂兮见虿，出门兮触螽。</p><p class="poem-stanza">巷有兮蚰蜓，邑多兮螳螂。</p><p class="poem-stanza">睹斯兮嫉贼，心为兮切伤。</p><p class="poem-stanza">俛念兮子胥，仰怜兮比干。</p><p class="poem-stanza">投剑兮脱冕，龙屈兮蜿蟤。</p><p class="poem-stanza">潜藏兮山泽，匍匐兮丛攒。</p><p class="poem-stanza">窥见兮溪涧，流水兮沄沄。</p><p class="poem-stanza">鼋鼍兮欣欣，鱣鲇兮延延。</p><p class="poem-stanza">群行兮上下，骈罗兮列陈。</p><p class="poem-stanza">自恨兮无友，特处兮茕茕。</p><p class="poem-stanza">冬夜兮陶陶，雨雪兮冥冥。</p><p class="poem-stanza">神光兮颎颎，鬼火兮荧荧。</p><p class="poem-stanza">修德兮困控，愁不聊兮遑生。</p><p class="poem-stanza">忧纡兮郁郁，恶所兮写情。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
